import type { QuestionGuidance } from "../../domain/questionHelpModel";

/*
 * Forge053+ step-by-step guides for cards that used to open one hint and then
 * the full solution. One JSON file per subject; each row is
 * { id, h, guidance } where h is identityHash(questionIdentity(card)), so a
 * guide never attaches to a changed card. The card data itself is untouched.
 * Files are generated by the round's integration step from reviewed batches.
 */
type Row = { id: string; h: string; guidance: QuestionGuidance };
const files = import.meta.glob<Row[]>("./*.json", { eager: true, import: "default" });
export const guidance053Rows: Row[] = Object.keys(files)
  .sort()
  .flatMap((path) => files[path]);
